import os

for root, dirs, files in os.walk('.'):
    # Skip hidden dirs and skill dirs to keep output focused
    dirs[:] = [d for d in dirs if not d.startswith('.') and d != '.codex']
    for f in files:
        print(os.path.join(root, f))

import sys

try:
    import defusedxml.minidom as minidom
    print("using defusedxml")
except ImportError:
    import xml.dom.minidom as minidom
    print("using stdlib minidom")

from xml.dom import Node

doc = minidom.parse('unpacked/word/document.xml')
paras = doc.getElementsByTagName("w:p")
print(f"Total paragraphs: {len(paras)}")
print("---")
for i, p in enumerate(paras):
    style_val = None
    for child in p.childNodes:
        if child.nodeType == Node.ELEMENT_NODE and child.tagName == "w:pPr":
            for c in child.childNodes:
                if c.nodeType == Node.ELEMENT_NODE and c.tagName == "w:pStyle":
                    style_val = c.getAttribute("w:val")
    texts = []
    for t in p.getElementsByTagName("w:t"):
        texts.append(t.firstChild.nodeValue if t.firstChild and t.firstChild.nodeType == Node.TEXT_NODE else "")
    for t in p.getElementsByTagName("w:delText"):
        texts.append("[del] " + (t.firstChild.nodeValue if t.firstChild and t.firstChild.nodeType == Node.TEXT_NODE else ""))
    content = "".join(texts).strip()
    print(f"[{i}] style={style_val} | {content[:120]}")

